/// Payload of the `Page.javascriptDialogOpening` event.
///
/// Fired when a JavaScript initiated dialog (alert, confirm, prompt, or onbeforeunload) is about to
/// open.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct JavascriptDialogOpeningEvent {
    /// Frame url.
    #[serde(rename = "url")]
    pub url: String,
    /// Frame id.
    ///
    /// **Experimental.**
    #[serde(rename = "frameId")]
    pub frame_id: FrameId,
    /// Message that will be displayed by the dialog.
    #[serde(rename = "message")]
    pub message: String,
    /// Dialog type.
    #[serde(rename = "type")]
    pub r#type: DialogType,
    /// True iff browser is capable showing or acting on the given dialog. When browser has no
    /// dialog handler for given target, calling alert while Page domain is engaged will stall
    /// the page execution. Execution can be resumed via calling Page.handleJavaScriptDialog.
    #[serde(rename = "hasBrowserHandler")]
    pub has_browser_handler: bool,
    /// Default dialog prompt.
    #[serde(
        rename = "defaultPrompt",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub default_prompt: Option<String>,
}

impl crate::Event for JavascriptDialogOpeningEvent {
    const NAME: &'static str = "Page.javascriptDialogOpening";
}

